function s(v) { return (typeof v === 'string' && !/^\{\{.*\}\}$/.test(v)) ? v : ''; }
function normV(v) { return s(v).replace(/^[vV]/, ''); }
var errors = [];
var op = s(input.op);
var arm = (input.arm && typeof input.arm === 'object' && !Array.isArray(input.arm)) ? input.arm : {};
var shipVersion = normV(input.ship_version);
if (!shipVersion) errors.push('缺 ship_version（這一趟出貨的版本號）');
if (s(arm.by) !== 'Leo') errors.push('沒有 Leo 的 ARM 簽核（簽核人讀到：' + (s(arm.by) || '(空)') + '）——沒有 ARM 就不建、不掛');
if (shipVersion && normV(arm.version) !== shipVersion) errors.push('ARM 簽的版本（' + (normV(arm.version) || '(空)') + '）對不上這趟出貨的版本（' + shipVersion + '）');
if (!/issuecomment-[0-9]+$/.test(s(arm.ref))) errors.push('ARM 缺出處：ref 要指到那則簽核留言（…#issuecomment-<id>）');
var slug = s(input.repo_slug);
if (!/^youlinhsieh\/[A-Za-z0-9._-]+$/.test(slug)) errors.push('repo_slug 只准 youlinhsieh/<repo>（讀到：' + (slug || '(空)') + '）');
var url = '';
var body = '';
var contentType = 'application/json';
if (op === 'create_release') {
  var tag = s(input.tag);
  var name = s(input.name);
  var text = s(input.body);
  var commit = s(input.target_commitish);
  if (!/^[A-Za-z0-9._-]{1,64}$/.test(tag)) errors.push('tag 格式不合：' + (tag || '(空)'));
  if (!name || name.length > 200) errors.push('name 空白或超過 200 字');
  if (text.length > 120000) errors.push('body 超過 120000 字');
  if (!/^[0-9a-f]{40}$/.test(commit)) errors.push('target_commitish 要是 40 碼 sha');
  url = 'https://api.github.com/repos/' + slug + '/releases';
  body = JSON.stringify({ tag_name: tag, name: name, body: text, target_commitish: commit });
} else if (op === 'upload_asset') {
  var rid = s(input.release_id);
  var aname = s(input.asset_name);
  var atext = (typeof input.asset_text === 'string') ? input.asset_text : '';
  var act = s(input.asset_content_type);
  if (!/^[0-9]{1,20}$/.test(rid)) errors.push('release_id 要是數字');
  if (!/^[A-Za-z0-9._-]{1,100}$/.test(aname)) errors.push('asset_name 格式不合：' + (aname || '(空)'));
  if (['application/json', 'text/plain', 'text/markdown'].indexOf(act) < 0) errors.push('asset_content_type 只准 json／純文字／markdown（二進位檔不經這條路）');
  if (!atext) errors.push('asset_text 空白');
  if (atext.length > 1500000) errors.push('asset_text 超過 1.5 MB（大檔不經這條路）');
  url = 'https://uploads.github.com/repos/' + slug + '/releases/' + rid + '/assets?name=' + encodeURIComponent(aname);
  body = atext;
  contentType = act;
} else {
  errors.push('op 只認 create_release／upload_asset（讀到：' + (op || '(空)') + '）');
}
return {
  go: errors.length === 0 ? 'yes' : 'no',
  errors: errors,
  op: op,
  url: errors.length === 0 ? url : '',
  content_type: contentType,
  body: errors.length === 0 ? body : ''
};

var send = (input && input.send) || {};
var op = (typeof input.op === 'string') ? input.op : '';
var raw = (send.data && typeof send.data.body === 'string') ? send.data.body : '';
var parsed = null;
try { parsed = JSON.parse(raw); } catch (e) {}
var ok = send.success === true && !!parsed;
var out = { contract: 'v1', ok: ok, refused: false, op: op, http_error: ok ? null : String(send.error || 'send 失敗（沒有回應內容）').slice(0, 300) };
if (ok && op === 'create_release') {
  out.release = { id: parsed.id, html_url: parsed.html_url, upload_url: parsed.upload_url, tag_name: parsed.tag_name, target_commitish: parsed.target_commitish };
  if (!parsed.id) { out.ok = false; out.http_error = '回應沒有 release id：' + raw.slice(0, 200); }
} else if (ok && op === 'upload_asset') {
  out.asset = { id: parsed.id, name: parsed.name, size: parsed.size, state: parsed.state };
  if (!parsed.id) { out.ok = false; out.http_error = '回應沒有 asset id：' + raw.slice(0, 200); }
}
if (!out.ok && raw) out.response_body = raw.slice(0, 300);
return out;

